const cacheAsyncFunc = (asyncFunc) => {
  const cache = new Map();
  const resQueue = [];
  let isChecking = false;

  const check = () => {
    if (resQueue.length === 0) {
      isChecking = false;
      return;
    }
    const { result, resolve, reject } = resQueue.shift();
    result.then(resolve, reject).finally(check);
  }

  return (...args) => {
    const key = JSON.stringify(args);

    let result;
    if (cache.has(key)) {
      result = cache.get(key);
    } else {
      result = asyncFunc(...args);
      cache.set(key, result);
    }

    const { promise, resolve, reject } = Promise.withResolvers();
    resQueue.push({
      result,
      resolve,
      reject,
    });

    if (!isChecking) {
      isChecking = true;
      check();
    }

    return promise;
  };
};
